A Simple User-Defined Function
CREATE FUNCTION east_or_west (
@long DECIMAL(9,6)
)
RETURNS CHAR(4) AS
BEGIN
DECLARE @return_value CHAR(4);
SET @return_value = 'same';
IF (@long > 0.00) SET @return_value = 'east';
IF (@long < 0.00) SET @return_value = 'west';
RETURN @return_value
END;
